<?php require '../config/auth.php';login_required('admin');$page_title='Placement Reports';$students=(int)$pdo->query('SELECT COUNT(*) c FROM students')->fetch()['c'];$companies=(int)$pdo->query('SELECT COUNT(*) c FROM companies')->fetch()['c'];$jobs=(int)$pdo->query('SELECT COUNT(*) c FROM jobs')->fetch()['c'];$selected=(int)$pdo->query("SELECT COUNT(DISTINCT student_id) c FROM applications WHERE status='selected'")->fetch()['c'];$pct=$students?round($selected/$students*100,2):0;$cw=$pdo->query("SELECT c.company_name,COUNT(a.id) applications,COUNT(CASE WHEN a.status='selected' THEN 1 END) selected FROM companies c LEFT JOIN jobs j ON j.company_id=c.id LEFT JOIN applications a ON a.job_id=j.id GROUP BY c.id ORDER BY selected DESC")->fetchAll();$dw=$pdo->query("SELECT department,COUNT(*) students,COUNT(DISTINCT CASE WHEN a.status='selected' THEN s.id END) selected FROM students s LEFT JOIN applications a ON a.student_id=s.id GROUP BY department")->fetchAll();require '../config/header.php';?><div class="head no-print"><div><h1>Placement Reports</h1><p>Print-ready placement summary.</p></div><button class="btn primary" onclick="window.print()">🖨 Print</button></div><div class="print"><h1>CareerBridge Placement Report</h1><p>Generated <?=date('d M Y, h:i A')?></p></div><div class="grid g4"><div class="card"><small class="muted">Students</small><div style="font:800 36px 'Plus Jakarta Sans'"><?=$students?></div></div><div class="card"><small class="muted">Companies</small><div style="font:800 36px 'Plus Jakarta Sans'"><?=$companies?></div></div><div class="card"><small class="muted">Jobs</small><div style="font:800 36px 'Plus Jakarta Sans'"><?=$jobs?></div></div><div class="card"><small class="muted">Placement %</small><div style="font:800 36px 'Plus Jakarta Sans'"><?=$pct?>%</div></div></div><div class="grid g2" style="margin-top:18px"><div class="card"><h3>Company-wise placement</h3><div class="tablewrap"><table class="table"><tr><th>Company</th><th>Applications</th><th>Selected</th></tr><?php foreach($cw as $x):?><tr><td><?=e($x['company_name'])?></td><td><?=$x['applications']?></td><td><?=$x['selected']?></td></tr><?php endforeach;?></table></div></div><div class="card"><h3>Department-wise placement</h3><div class="tablewrap"><table class="table"><tr><th>Department</th><th>Students</th><th>Selected</th></tr><?php foreach($dw as $x):?><tr><td><?=e($x['department']?:'Not specified')?></td><td><?=$x['students']?></td><td><?=$x['selected']?></td></tr><?php endforeach;?></table></div></div></div><?php require '../config/footer.php';?>
